document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("room-area-form"),t=document.getElementById("room-area-result");e&&e.addEventListener("submit",function(e){e.preventDefault();const n=parseFloat(document.getElementById("room-length").value),o=parseFloat(document.getElementById("room-width").value);if(n<=0||o<=0)return t.textContent="Please enter positive values for length and width.",void 0;const r=n*o,d=.092903*r;t.innerHTML=`\n        <div class="result-section">\n          <p><strong>Room Area:</strong> ${r.toFixed(2)} sq ft</p>\n          <p><strong>Room Area:</strong> ${d.toFixed(2)} m²</p>\n        </div>\n        <div class="result-tips">\n          <p><em>💡 Add 5-10% extra material for cuts and waste</em></p>\n          <p><em>📏 For flooring: ${(1.1*r).toFixed(0)} sq ft recommended</em></p>\n        </div>\n      `})});